  .option('--updates <json>', 'JSON updates')
  .option('--force', 'Force refinement')
  .action(async (id, options) => {
    const refiner = new Refiner();
    const updates = options.updates ? JSON.parse(options.updates) : {};
    const updated = await refiner.refine(parseInt(id), options.feedback, updates, options.force);
